import { Column, Entity, JoinColumn, ManyToOne, Index } from 'typeorm';
import { FieldTransformer } from '../../../shared/utils/helpers';
import { BaseEntity } from '../../../shared/entities/base-entity.entity';
import { User } from '../../user/entities/user.entity';
import { CalendarPlatforms } from '../../platform-integrations/domain/calendar-platforms.enum';
import { NotificationType } from '../../../shared/domain/notification-type.enum';

@Entity('notifications')
export class Notification extends BaseEntity {
  constructor({ id, ...event }: Partial<Notification> = {}, options = { generateId: false }) {
    super(id, options);
    Object.assign(this, { ...event });
  }

  @Index()
  @Column({
    type: 'uuid',
    nullable: false,
  })
  user_id?: string;

  @Column({
    type: 'varchar',
    length: 255,
    unique: true,
  })
  platform?: CalendarPlatforms;

  @Column({
    type: 'varchar',
    length: 255,
    unique: true,
    transformer: FieldTransformer,
  })
  platform_account?: string;

  @Column({
    type: 'varchar',
    length: 255,
    unique: true,
    transformer: FieldTransformer,
  })
  calendar_id?: string;

  @Column({
    type: 'varchar',
    length: 255,
    unique: true,
  })
  external_id?: string;

  @Column({
    type: 'varchar',
    length: 2500,
    transformer: FieldTransformer,
  })
  summary?: string;

  @Column({
    type: 'text',
    transformer: FieldTransformer,
  })
  description?: string;

  @Column({
    type: 'timestamptz',
  })
  event_begins?: Date;

  @Column({
    type: 'timestamptz',
  })
  event_ends?: Date;

  @Column({
    type: 'boolean',
    default: false,
  })
  is_dismissed?: boolean;

  @Column({
    type: 'varchar',
    length: 255,
  })
  dismiss_reason?: string;

  @Column({
    type: 'boolean',
    default: false,
  })
  received?: boolean;

  @ManyToOne(() => User, (user) => user.notifications, { onDelete: 'CASCADE', onUpdate: 'CASCADE' })
  @JoinColumn({ name: 'user_id' })
  user?: User;

  @Column({
    type: 'jsonb',
    default: null,
    nullable: true,
    select: false,
    transformer: BaseEntity.encryptJSONField('external_metadata'),
  })
  external_metadata?: any;

  @Index()
  @Column({
    type: 'varchar',
    length: 100,
    nullable: true,
    default: NotificationType.CALENDAR_EVENT,
  })
  notification_type?: NotificationType;

  @Column({
    type: 'varchar',
    length: 500,
    nullable: true,
  })
  action_url?: string;

  @Index()
  @Column({
    type: 'uuid',
    nullable: true,
  })
  related_entity_id?: string;

  @Column({
    type: 'varchar',
    length: 100,
    nullable: true,
  })
  related_entity_type?: string;
}
